// SessionContext is a context associated with a user's
// web session. An instance of the context is created for
// each web session generated for the user and provides
// a basic client cache for remote auth server connections.
type SessionContext struct {
	log    logrus.FieldLogger
	user   string
	clt    auth.ClientI
	parent *sessionCache
	// resources is persistent resource store this context is bound to.
	// The store maintains a list of resources between session renewals
	resources *sessionResources
	// session refers the web session created for the user.
	session services.WebSession

	mu        sync.Mutex
	remoteClt map[string]auth.ClientI
}

// String returns the text representation of this context
func (c *SessionContext) String() string {
	return fmt.Sprintf("WebSession(user=%v,id=%v,expires=%v,bearer=%v,bearer_expires=%v)",
		c.user,
		c.session.GetName(),
		c.session.GetExpiryTime(),
		c.session.GetBearerToken(),
		c.session.GetBearerTokenExpiryTime(),
	)
}

// AddClosers adds the specified closers to this context
func (c *SessionContext) AddClosers(closers ...io.Closer) {
	c.resources.addClosers(closers...)
}

// RemoveCloser removes the specified closer from this context
func (c *SessionContext) RemoveCloser(closer io.Closer) {
	c.resources.removeCloser(closer)
}
//
// Note: the caller must prompt the user to tap the U2F token.
func AuthenticateSignChallenge(ctx context.Context, facet string, challenges ...AuthenticateChallenge) (*AuthenticateChallengeResponse, error) {
	base64 := base64.URLEncoding.WithPadding(base64.NoPadding)

	// Convert from JS-centric github.com/tstranex/u2f format to a more
	// wire-centric github.com/flynn/u2f format.
	type authenticateRequest struct {
		orig       AuthenticateChallenge
		clientData []byte
		converted  u2ftoken.AuthenticateRequest
	}
	authRequests := make([]authenticateRequest, 0, len(challenges))
	for _, chal := range challenges {
		kh, err := base64.DecodeString(chal.KeyHandle)
		if err != nil {
			return nil, trace.BadParameter("invalid KeyHandle %q in AuthenticateChallenge: %v", chal.KeyHandle, err)
		}
		cd := u2f.ClientData{
			Challenge: chal.Challenge,
			Origin:    facet,
			Typ:       "navigator.id.getAssertion",
		}
		cdRaw, err := json.Marshal(cd)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		chHash := sha256.Sum256(cdRaw)
		appHash := sha256.Sum256([]byte(chal.AppID))
		authRequests = append(authRequests, authenticateRequest{
			orig:       chal,
			clientData: cdRaw,
			converted: u2ftoken.AuthenticateRequest{
				KeyHandle:   kh,
				Challenge:   chHash[:],
				Application: appHash[:],
			},
		})
	}

	var matchedAuthReq *authenticateRequest
	var authResp *u2ftoken.AuthenticateResponse
	if err := pollLocalDevices(ctx, func(t *u2ftoken.Token) error {
		var errs []error
		for _, req := range authRequests {
			if err := t.CheckAuthenticate(req.converted); err != nil {
				if err != u2ftoken.ErrUnknownKeyHandle {
					errs = append(errs, trace.Wrap(err))
				}
				continue
			}
			res, err := t.Authenticate(req.converted)
			if err == u2ftoken.ErrPresenceRequired {
				continue
			} else if err != nil {
				errs = append(errs, trace.Wrap(err))
				continue
			}
			matchedAuthReq = &req
			authResp = res
			return nil
		}
		if len(errs) > 0 {
			return trace.NewAggregate(errs...)
		}
		return errAuthNoKeyOrUserPresence

